NEW_FILES = {'export_drawings.py': '"""\nexport_drawings.py -- write the orrery\'s stored drawings into\ndata/drawings/, one file per drawing, for the website to pull and draw.\n\nRUN COMMAND\n-----------\nOpen this file in VS Code and click Run. It takes no arguments.\n\n    python export_drawings.py\n\norrery_maintenance_run.py runs it on every maintenance run, as a\nGENERATOR, so a drawing cannot fall behind the rows it is drawn from.\ntest_drawings_export.py, among the checkers, then re-draws each one and\nfails if the file does not hold the same dots.\n\nWHY A DRAWING IS STORED (Tony\'s ruling of 2026-10-11, L-421, option A)\n---------------------------------------------------------------------\nSome shapes are scattered dots placed by random numbers, or by a model\nthe browser would have to rewrite: the Hills cloud is dots along orbits\nfollowing Nesvorny et al. (2025), Fig. 3. The orrery places them; the\nwebsite draws the dots it is given and places none itself. So there is\none way of placing them, the orrery\'s, and the website\'s cloud is the\norrery\'s cloud. A shape that is a few numbers and a formula (a sphere,\na ring) is not stored: the numbers are the drawing, and the website\ncomputes it from the served rows. The other scattered-dot shells (the\nstreamer band, the outer cloud\'s clumps, the galactic tide) can join\nthis list later; that work is its own ledger item.\n\nWHAT IT WRITES\n--------------\ndata/drawings/<name>.json for each entry in DRAWINGS:\n\n    schema        1\n    drawing       the drawing\'s name, the same as the file\'s\n    what          one sentence on what the dots are\n    made_by       the function that places the dots\n    frame         the frame the coordinates are in\n    unit          "au"\n    rounding      how each coordinate was rounded, and why that is safe\n    settings      the drawing\'s settings: orbits, dots per orbit, seed\n    rows          the constants_new.py rows the dots are placed from\n    rows_sha256   sha256 of those rows\' values (sorted JSON), so a\n                  change to any of them shows as a change here\n    dots          how many dots\n    plane_tilt_deg  the tilt to the ecliptic of the plane through THESE\n                  dots, as rounded, to 0.1 degree: the figure the\n                  website\'s own check fits again from the served dots\n    x, y, z       the dots, one list each, whole AU\n\nDETERMINISTIC ON PURPOSE\n------------------------\nThe same rows give the same file: the seed is fixed and nothing in the\nfile is a date or a commit. The file is written only when its content\nwould change, always with LF line endings, so an unchanged drawing\nnever shows in GitHub Desktop. As with data/constants_export.json, the\ngallery records the orrery SHA it pulled the file at.\n\nThe coordinates are rounded to whole AU. The Hills cloud spans about\n20,000 AU and its innermost dots sit near 200 AU, so half an AU moves\nno dot a visitor can see, and the file is about half the size. The\nplane\'s tilt is fitted after rounding.\n\nWrites nothing, and exits 1, if a drawing cannot be made.\n\nRole: devtool\nDomain: dev_tools\n\nModule created: October 11, 2026 with Anthropic\'s Claude Opus 5.5\n(L-421, the website half of the inner Oort cloud: the first stored\ndrawing, the Hills cloud).\n"""\n\nimport hashlib\nimport json\nimport os\nimport sys\n\nDRAWINGS_DIR = os.path.join("data", "drawings")\nSCHEMA = 1\n\n\ndef _hills_cloud():\n    """The Hills cloud\'s file content, as a dict, from the store."""\n    import hills_cloud_sampler as hcs\n    rows = hcs.rows_from_store()\n    dots = hcs.drawn_hills_cloud(rows)\n    x = [int(round(v)) for v in dots[\'x\']]\n    y = [int(round(v)) for v in dots[\'y\']]\n    z = [int(round(v)) for v in dots[\'z\']]\n    tilt = hcs.plane_tilt_deg(*(list(map(float, axis)) for axis in (x, y, z)))\n    return {\n        "schema": SCHEMA,\n        "drawing": "hills_cloud",\n        "what": ("The Hills cloud, the inner Oort cloud, as dots along "\n                 "orbits following Nesvorny et al. (2025), Fig. 3 "\n                 "(arXiv:2502.11252): a disk tilted to the ecliptic, "\n                 "with two arms."),\n        "made_by": "hills_cloud_sampler.drawn_hills_cloud()",\n        "frame": ("ecliptic and equinox of J2000, centred on the Sun, "\n                  "the orrery\'s drawing frame"),\n        "unit": "au",\n        "rounding": ("each coordinate to the nearest whole AU: a drawing, "\n                     "not a measurement, and half an AU is invisible at "\n                     "this scale"),\n        "settings": dots[\'settings\'],\n        "rows": list(hcs.ROW_NAMES),\n        "rows_sha256": rows_sha256(rows),\n        "dots": len(x),\n        "plane_tilt_deg": round(tilt, 1),\n        "x": x, "y": y, "z": z,\n    }\n\n\n# name -> function returning the file\'s content. A new stored drawing\n# is one line here, and test_drawings_export.py checks every entry.\nDRAWINGS = {\n    "hills_cloud": _hills_cloud,\n}\n\n\ndef rows_sha256(rows):\n    """sha256 of the rows\' values, as sorted JSON."""\n    text = json.dumps(rows, sort_keys=True, ensure_ascii=True,\n                      allow_nan=False)\n    return hashlib.sha256(text.encode("ascii")).hexdigest()\n\n\ndef render(content):\n    """The exact text written to disk: the header indented, one line per\n    coordinate list, so a reader can open the file and see what it is."""\n    head = {k: v for k, v in content.items() if k not in ("x", "y", "z")}\n    text = json.dumps(head, indent=2, ensure_ascii=True, allow_nan=False)\n    assert text.endswith("\\n}")\n    lines = [text[:-2]]\n    for axis in ("x", "y", "z"):\n        lines.append(\',\\n  "%s": %s\' % (axis, json.dumps(\n            content[axis], separators=(",", ":"))))\n    return "".join(lines) + "\\n}\\n"\n\n\ndef path_of(project_dir, name):\n    return os.path.join(project_dir, DRAWINGS_DIR, name + ".json")\n\n\ndef main():\n    project_dir = os.path.dirname(os.path.abspath(__file__))\n    print("=" * 70)\n    print("  DRAWINGS EXPORT -- %s/" % DRAWINGS_DIR.replace(os.sep, "/"))\n    print("=" * 70)\n    made = {}\n    for name, build in DRAWINGS.items():\n        try:\n            made[name] = render(build())\n        except Exception as exc:          # report, write nothing\n            print("FAIL: the drawing %r could not be made (%s: %s). "\n                  "Nothing written." % (name, type(exc).__name__, exc))\n            return 1\n    written = 0\n    for name, text in made.items():\n        target = path_of(project_dir, name)\n        old = None\n        if os.path.exists(target):\n            with open(target, "rb") as handle:\n                old = handle.read().replace(b"\\r\\n", b"\\n").decode("utf-8")\n        content = json.loads(text)\n        if old == text:\n            action = "unchanged, not written"\n        else:\n            os.makedirs(os.path.dirname(target), exist_ok=True)\n            with open(target, "w", encoding="utf-8", newline="") as handle:\n                handle.write(text)\n            action = "written" if old is not None else "created"\n            written += 1\n        print("  %-14s %s: %d dots, plane tilted %.1f deg, %d bytes, "\n              "rows sha256 %s"\n              % (name, action, content["dots"], content["plane_tilt_deg"],\n                 len(text), content["rows_sha256"][:12]))\n    print("")\n    print("Drawings export: %d drawing(s) (%s), %d written."\n          % (len(made), ", ".join(made), written))\n    return 0\n\n\nif __name__ == "__main__":\n    sys.exit(main())\n', 'test_drawings_export.py': '"""\ntest_drawings_export.py - each stored drawing in data/drawings/ is the\ndrawing its rows give today, git tracks it, and each check can fail.\n\nFor every entry in export_drawings.DRAWINGS it checks:\n\n    the file      data/drawings/<name>.json exists and reads as JSON\n    tracked       git does not ignore the file -- an ignored file never\n                  reaches GitHub, and the website\'s pull of it would fail\n                  with nothing here saying why (Tony\'s question of\n                  2026-10-11 about ignored JSON files in data/)\n    the dots      drawing it again from constants_new.py gives the same\n                  file, byte for byte after line endings; so the file\n                  follows the rows and the sampler, and nobody edited it\n    the count     x, y and z each hold "dots" entries, and dots is the\n                  settings\' orbits times dots per orbit\n    the tilt      the plane through the file\'s own dots is tilted as the\n                  file records, and within the sampler\'s tolerance of\n                  HILLS_CLOUD_TILT_DEG, the paper\'s "about 30" (for the\n                  Hills cloud)\n\nA check that passes is only worth something if it can fail, so three\nfaults are planted first, each in memory, and each must be caught:\n\n    planted                                  must be caught by\n    one dot moved by 1,000 AU                the dots\n    the eccentricity row set to 0.5          the dots\n    git reporting the file as ignored        tracked\n\nThe last line starts "DRAWINGS EXPORT:", which the maintenance run\nquotes. It names each drawing, its dots, its tilt and its sha256.\n\nRun (VS Code Run button, or):\n    python test_drawings_export.py\n\nNeeds git on the PATH, as Constants change does; without it the run\nfails and says so rather than passing unchecked.\n\nRole: dev_tools\nDomain: orrery\n\nModule created: October 11, 2026 with Anthropic\'s Claude Opus 5.5 (L-421,\nthe website half of the inner Oort cloud)\n"""\nimport hashlib\nimport json\nimport os\nimport subprocess\nimport sys\n\nimport export_drawings as ed\nimport hills_cloud_sampler as hcs\n\nPROJECT_DIR = os.path.dirname(os.path.abspath(__file__))\n\n\ndef git_ignored(path):\n    """True if git ignores path, False if not; raises if git cannot say."""\n    result = subprocess.run(\n        ["git", "check-ignore", "-q", "--no-index",\n         os.path.relpath(path, PROJECT_DIR)],\n        cwd=PROJECT_DIR, capture_output=True, text=True)\n    if result.returncode == 0:\n        return True\n    if result.returncode == 1:\n        return False\n    raise RuntimeError("git check-ignore exited %d: %s"\n                       % (result.returncode, result.stderr.strip()))\n\n\ndef check_one(name, text_on_disk, text_now, path, ignored=git_ignored):\n    """Failures for one drawing, as sentences, and what was examined."""\n    failures = []\n    try:\n        content = json.loads(text_on_disk)\n    except ValueError as exc:\n        return ["%s: the file does not read as JSON (%s)" % (name, exc)], {}\n    try:\n        if ignored(path):\n            failures.append("%s: git ignores %s, so it never reaches GitHub "\n                            "and the website cannot pull it -- change "\n                            ".gitignore" % (name, os.path.relpath(path, PROJECT_DIR)))\n    except (OSError, RuntimeError) as exc:\n        failures.append("%s: could not ask git whether the file is ignored "\n                        "(%s)" % (name, exc))\n    if text_on_disk != text_now:\n        now = json.loads(text_now)\n        moved = [key for key in now if now.get(key) != content.get(key)]\n        failures.append("%s: the file is not the drawing its rows give "\n                        "today -- these fields differ: %s. Run "\n                        "export_drawings.py" % (name, ", ".join(moved) or\n                                                "(layout only)"))\n    n = content.get("dots")\n    settings = content.get("settings", {})\n    lengths = [len(content.get(axis, [])) for axis in ("x", "y", "z")]\n    want = settings.get("n_orbits", 0) * settings.get("points_per_orbit", 0)\n    if lengths != [n, n, n] or n != want:\n        failures.append("%s: %s dots recorded, x/y/z hold %s, settings give "\n                        "%d" % (name, n, lengths, want))\n    tilt = None\n    if lengths == [n, n, n] and n:\n        tilt = hcs.plane_tilt_deg(*(list(map(float, content[axis]))\n                                    for axis in ("x", "y", "z")))\n        if abs(round(tilt, 1) - content.get("plane_tilt_deg", -999)) > 0.05:\n            failures.append("%s: the plane through the file\'s dots is tilted "\n                            "%.1f deg, the file records %s"\n                            % (name, tilt, content.get("plane_tilt_deg")))\n        if name == "hills_cloud":\n            paper = hcs.rows_from_store()["HILLS_CLOUD_TILT_DEG"]\n            if abs(tilt - paper) > 10.0:\n                failures.append("%s: the dots\' plane is tilted %.1f deg, not "\n                                "within 10 deg of the paper\'s %s"\n                                % (name, tilt, paper))\n    info = {"dots": n, "tilt": tilt,\n            "sha256": hashlib.sha256(text_on_disk.encode("utf-8")).hexdigest()}\n    return failures, info\n\n\ndef _planted(text_now, path):\n    """Three faults, each with the check that must catch it."""\n    out = []\n    moved = json.loads(text_now)\n    moved["x"][0] += 1000\n    out.append(("one dot moved by 1,000 AU", ed.render(moved), text_now,\n                git_ignored, "is not the drawing"))\n    rows = hcs.rows_from_store()\n    rows["HILLS_CLOUD_ECCENTRICITY"] = 0.5\n    real = hcs.rows_from_store\n    hcs.rows_from_store = lambda: dict(rows)\n    try:\n        other = ed.render(ed.DRAWINGS["hills_cloud"]())\n    finally:\n        hcs.rows_from_store = real\n    out.append(("the eccentricity row set to 0.5", text_now, other,\n                git_ignored, "is not the drawing"))\n    out.append(("git reporting the file as ignored", text_now, text_now,\n                lambda _p: True, "git ignores"))\n    return out\n\n\ndef main():\n    print("=" * 70)\n    print("  DRAWINGS EXPORT CHECK -- data/drawings/ against the rows")\n    print("=" * 70)\n    problems = []\n    texts_now = {}\n    for name, build in ed.DRAWINGS.items():\n        texts_now[name] = ed.render(build())\n\n    caught = 0\n    planted = _planted(texts_now["hills_cloud"],\n                       ed.path_of(PROJECT_DIR, "hills_cloud"))\n    for label, on_disk, now, ignored, expect in planted:\n        failures, _ = check_one("hills_cloud", on_disk, now,\n                                ed.path_of(PROJECT_DIR, "hills_cloud"),\n                                ignored)\n        hit = any(expect in line for line in failures)\n        print("  planted: %-36s %s" % (label, "caught" if hit else "MISSED"))\n        if hit:\n            caught += 1\n        else:\n            problems.append("planted fault not caught: " + label)\n    print("")\n\n    named = []\n    for name in ed.DRAWINGS:\n        path = ed.path_of(PROJECT_DIR, name)\n        if not os.path.exists(path):\n            problems.append("%s: %s is missing -- run export_drawings.py"\n                            % (name, os.path.relpath(path, PROJECT_DIR)))\n            continue\n        with open(path, "rb") as handle:\n            on_disk = handle.read().replace(b"\\r\\n", b"\\n").decode("utf-8")\n        failures, info = check_one(name, on_disk, texts_now[name], path)\n        problems.extend(failures)\n        tilt = "%.1f deg" % info["tilt"] if info.get("tilt") is not None else "?"\n        print("  %-14s %s dots, plane tilted %s, tracked by git: %s, "\n              "sha256 %s" % (name, info.get("dots"), tilt,\n                             "no" if any("git ignores" in f for f in failures)\n                             else "yes", info.get("sha256", "")[:12]))\n        if not failures:\n            named.append("%s %s dots, tilt %s, sha256 %s"\n                         % (name, info["dots"], tilt, info["sha256"][:12]))\n    print("")\n    if problems:\n        for line in problems:\n            print("FAIL: " + line)\n        print("DRAWINGS EXPORT: FAIL -- %d problem(s)" % len(problems))\n        return 1\n    print("DRAWINGS EXPORT: PASS -- %d of %d planted faults caught; %s"\n          % (caught, len(planted), "; ".join(named)))\n    return 0\n\n\nif __name__ == "__main__":\n    sys.exit(main())\n'}

MARKER = "palomas_orrery.py"


def main():
    root = os.path.dirname(os.path.abspath(__file__))
    if not os.path.exists(os.path.join(root, MARKER)):
        print("ERROR: %s is not beside this script, so this is not the "
              "orrery's repository folder. Nothing written." % MARKER)
        return 1
    out, notes, lines = {}, [], []
    applied_already = 0
    for path, pairs in EDITS.items():
        full = os.path.join(root, path)
        if not os.path.exists(full):
            print("ERROR: %s is missing. Nothing written." % path)
            return 1
        raw = open(full, "rb").read()
        text = raw.replace(b"\r\n", b"\n").decode("utf-8")
        if b"\r\n" in raw:
            notes.append("note: %s was CRLF in the working copy; written LF"
                         % path)
        if all(text.count(new) >= 1 for old, new in pairs) and not any(
                text.count(old) == 1 and old not in new for old, new in pairs):
            applied_already += 1
            lines.append("ok  %-34s already applied" % path)
            continue
        for i, (old, new) in enumerate(pairs, 1):
            n = text.count(old)
            if n != 1:
                print("ANCHOR FAIL: %s, edit %d of %d: expected 1 match, "
                      "found %d. Nothing written." % (path, i, len(pairs), n))
                print("  the anchor begins: %r" % old[:100])
                return 1
            if any(ord(c) > 127 for c in new):
                print("ERROR: edit %d for %s inserts non-ASCII. Nothing "
                      "written." % (i, path))
                return 1
            text = text.replace(old, new)
            lines.append("ok  %-34s edit %d of %d" % (path, i, len(pairs)))
        out[path] = text
    created = []
    for path, content in NEW_FILES.items():
        full = os.path.join(root, path)
        if os.path.exists(full):
            have = open(full, "rb").read().replace(b"\r\n", b"\n").decode("utf-8")
            if have == content:
                lines.append("ok  %-34s already present, identical" % path)
                continue
            print("ERROR: %s already exists and differs from this patch's "
                  "copy. Nothing written. Delete it, or tell Claude." % path)
            return 1
        out[path] = content
        created.append(path)
    for path, text in out.items():
        with open(os.path.join(root, path), "w", encoding="utf-8",
                  newline="") as handle:
            handle.write(text)
    for line in lines:
        print(line)
    for path in created:
        print("ok  %-34s created" % path)
    for line in notes:
        print(line)
    if not out:
        print("")
        print("already applied: nothing written.")
    else:
        print("")
        print("stamps updated: module docstrings of hills_cloud_sampler.py, "
              "solar_visualization_shells.py, orrery_maintenance_run.py, "
              "palomas_orrery_dashboard.py")
        print("patch applied: %d file(s) edited, %d created."
              % (len(out) - len(created), len(created)))
    print("")
    print("NEXT:")
    print("  1. Run orrery_maintenance_run.py. Expect \"Drawings export ... rewrote "
          "data/drawings/hills_cloud.json\",")
    print("     \"Drawings export check ... PASS -- 3 of 3 planted faults "
          "caught\",")
    print("     \"23 of 23 gating checkers passed\" and, on the provenance "
          "scanner's line,")
    print("     \"0 TIER-1 -- the push gate holds\".")
    print("  2. Move this script into documentation/; commit and push. The "
          "commit")
    print("     includes the new file data/drawings/hills_cloud.json.")
    print("  3. Tell Claude the pushed SHA; the website half builds on it.")
    return 0


if __name__ == "__main__":
    sys.exit(main())
